37	// Customer per-server backup retention: keep only the latest N backups. Older
38	// ones are pruned after every successful backup so they never pile up.
39	const CUSTOMER_BACKUP_KEEP = 2;
40	
41	// Job types whose terminal failure genuinely leaves the VM in a bad/unknown
42	// run or disk state — only these should mark the server ERROR. Everything else
43	// (backup, snapshot-create, control-panel ops, SSL, migrate copy, game update…)
44	// is a side operation that doesn't touch the VM's run state.
45	//
46	// DISK_EXPAND is deliberately ABSENT: growing a disk never changes the VM's run
47	// state, so a failed expansion must leave the server RUNNING/STOPPED as it was.
48	// Its money is unwound by reconcileFailedJob instead.
49	const VM_STATE_FAILURE_JOBS = new Set<string>([
50	  "PROVISION", "REINSTALL", "DELETE", "RESIZE", "START", "STOP",
51	  "REBOOT", "SUSPEND", "UNSUSPEND", "BACKUP_RESTORE", "SNAPSHOT_ROLLBACK",
52	]);
