68	/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
69	async function nodeFor(server: any) {
70	  const n =
71	    server.node ??
72	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
73	    (await db.node.findFirst({ where: { enabled: true } }));
74	  if (!n) {
75	    // No Node rows yet — use the env-configured primary via the global client.
76	    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
77	  }
78	  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
79	}
