81	/** YAML-safe indent of a multi-line script under a `content: |` block. */
82	function indentBlock(text: string, spaces: number): string {
83	  const pad = " ".repeat(spaces);
84	  return text.split("\n").map((l) => pad + l).join("\n");
85	}
