460	async function suspend(job: Job, unsuspend: boolean) {
461	  const server = await loadServer(job);
462	  if (SANDBOX) {
463	    if (unsuspend) {
464	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null, suspendReason: null } });
465	    } else {
466	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
467	    }
468	    return;
469	  }
470	  const { conn, row: nodeRow } = await nodeFor(server);
471	  if (unsuspend) {
472	    // The dedicated IP was returned to the pool while suspended — re-allocate one
473	    // and reconfigure the public network before starting the VM back up.
474	    if (server.vmid) {
475	      const { getSettingBool: _sb } = await import("../lib/settings");
476	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
477	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
478	      let reconfigured = alreadyHas ? true : false;
479	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
480	        try {
481	          const d = await allocateDedicatedIp(server.id, server.vmid);
482	          if (d) {
483	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
484	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
485	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
486	            });
487	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
488	            reconfigured = true;
489	          }
490	        } catch (e) {
491	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
492	        }
493	      }
494	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
495	      // the Virtual MAC + failover IP that suspend released back to the pool — that
496	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
497	      // with a valid, non-conflicting network instead of a dead public config.
498	      if (!reconfigured) {
499	        try {
500	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
501	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
502	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
503	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
504	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
505	          });
506	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
507	        } catch (e) {
508	          console.error("[worker] NAT fallback on unsuspend failed", e);
509	        }
510	      }
511	    }
512	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null, suspendReason: null } });
513	    if (!SANDBOX) await syncPortForwards();
514	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
515	    await conn.waitForTask(upid);
516	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
517	  } else {
518	    try {
519	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
520	      await conn.waitForTask(upid);
521	    } catch { /* may already be stopped */ }
522	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
523	    if (!SANDBOX) await syncPortForwards();
524	    // Return the dedicated IP to the pool while the server is suspended, so it
525	    // can be handed to a paying server. Re-allocated on unsuspend.
526	    if (ovhConfigured()) {
527	      try {
528	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
529	        if (had) {
530	          await releaseDedicatedIp(server.id);
531	          // MUST also clear the address off the server: `Server.ipAddress` is UNIQUE,
532	          // so leaving the released IP here makes the next server that claims it fail
533	          // with P2002 — that server then silently lands on NAT while its OVH Virtual
534	          // MAC stays allocated and billable. (NAT servers keep their private IP.)
535	          await db.server.update({
536	            where: { id: server.id },
537	            data: { ipAddress: null, ipv6: null },
538	          });
539	        }
540	      } catch (e) {
541	        console.error("[worker] release dedicated IP on suspend failed", e);
542	      }
543	    }
544	  }
545	}
