555	async function resize(job: Job) {
556	  const server = await loadServer(job);
557	  const payload = (job.payload ?? {}) as { planId?: string };
558	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
559	  if (!newPlan) throw new Error("resize: target plan not found");
560	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
561	
562	  // Any separately-purchased extra disk is ADDITIVE to whichever plan the server
563	  // sits on, so it survives the plan change untouched — `Server.extraDiskGB` is
564	  // never written here. Sizes below are therefore always the EFFECTIVE size
565	  // (new plan + extra); using the bare plan size would ask Proxmox to SHRINK the
566	  // disk of any server carrying extra storage, and the resize would hard-fail.
567	  const newTotalDiskGB = effectiveDiskGB(newPlan.diskGB, server.extraDiskGB);
568	  const currentTotalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
569	  const diskLine =
570	    server.extraDiskGB > 0
571	      ? `${newTotalDiskGB} GB disk (${newPlan.diskGB} GB plan + ${server.extraDiskGB} GB added storage)`
572	      : `${newPlan.diskGB} GB disk`;
573	
574	  if (SANDBOX) {
575	    await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
576	    await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
577	      `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
578	      `/dashboard/servers/${server.id}`);
579	    return;
580	  }
581	
582	  const { conn } = await nodeFor(server);
583	  const wasRunning = server.status === "RUNNING";
584	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
585	    cores: newPlan.cpuCores,
586	    memory: newPlan.ramMB,
587	  });
588	  if (newTotalDiskGB > currentTotalDiskGB) {
589	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
590	      disk: "scsi0",
591	      size: `${newTotalDiskGB}G`,
592	    });
593	  }
594	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
595	  // CPU/RAM changes need a power cycle to apply
596	  if (wasRunning) {
597	    try {
598	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
599	      await conn.waitForTask(stopUpid, 120_000);
600	    } catch {
601	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
602	      await conn.waitForTask(stopUpid);
603	    }
604	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
605	    await conn.waitForTask(startUpid);
606	  }
607	  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
608	    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
609	    `/dashboard/servers/${server.id}`);
610	}
