938	async function runJob(job: Job) {
939	  // The job is already atomically claimed (status RUNNING, attempts incremented)
940	  // by the loop's compare-and-swap before we get here — see the CAS in main().
941	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
942	  try {
943	    await handlers[job.type](job);
944	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
945	    console.log(`[worker] job ${job.id} DONE`);
946	  } catch (e: any) {
947	    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
948	    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
949	    // leak the server's root password into the thrown message. Redact it before
950	    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
951	    // sever the match. Best-effort — never let redaction lookup fail the job path.
952	    if (job.serverId) {
953	      try {
954	        const s = await db.server.findUnique({
955	          where: { id: job.serverId },
956	          select: { rootPassword: true, rootPasswordEnc: true },
957	        });
958	        const pw = s ? serverRootPassword(s) : null;
959	        if (pw) error = error.split(pw).join("***");
960	      } catch {
961	        /* best-effort redaction */
962	      }
963	    }
964	    error = error.slice(0, 2000);
965	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
966	    const current = await db.job.findUnique({ where: { id: job.id } });
967	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
968	    await db.job.update({
969	      where: { id: job.id },
970	      data: { status: retriable ? "QUEUED" : "FAILED", error },
971	    });
972	    if (!retriable) {
973	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
974	      if (job.serverId) {
975	        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
