1003	/**
1004	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
1005	 * killed worker leaves a job RUNNING forever, which permanently blocks the
1006	 * server's "one in-flight job" guard and strands it in a transitional state.
1007	 */
1008	async function reapStuckJobs() {
1009	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
1010	  for (const job of stuck) {
1011	    const retriable = job.attempts < MAX_ATTEMPTS;
1012	    await db.job.update({
1013	      where: { id: job.id },
1014	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
1015	    });
1016	    if (!retriable) {
1017	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
1018	      if (job.serverId) {
1019	        const s = await db.server.findUnique({ where: { id: job.serverId } });
1020	        if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
1021	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
1022	        }
1023	      }
1024	    }
1025	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
1026	  }
1027	}
