export async function orderServer(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  // Spend path: never move a customer's money while an admin is impersonating them.
  await assertNotImpersonating();
  // Refuse new orders once the user is at their server cap.
  const limitErr = await serverLimitError(user.id);
  if (limitErr) return { error: limitErr };
  const parsed = orderSchema.safeParse({
    planId: formData.get("planId"),
    osTemplateId: formData.get("osTemplateId"),
    hostname: formData.get("hostname"),
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid input." };

  const plan = await db.plan.findUnique({ where: { id: parsed.data.planId } });
  const os = await db.osTemplate.findUnique({ where: { id: parsed.data.osTemplateId } });
  if (!plan?.active || !os?.active) return { error: "Plan or OS not available." };

  // Image requirements (control panels/apps need more resources)
  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
    return {
      error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
    };
  }

  const cap = await capacityCheck(plan.id);
  if (!cap.ok) return { error: cap.reason };

  // Optional: node (location) selection, else auto-schedule
  const requestedNodeId = String(formData.get("nodeId") ?? "");
  let nodeId: string | null = null;
  if (requestedNodeId) {
    const n = await db.node.findFirst({ where: { id: requestedNodeId, enabled: true } });
    if (!n) return { error: "Selected location is not available." };
    nodeId = n.id;
  } else {
    const n = await scheduleNode(plan.ramMB);
    nodeId = n?.id ?? null;
  }

  // Add-ons (booleans)
  const addons = {
    malwareScanner: formData.get("addon_malware") === "1",
    dailyBackup: formData.get("addon_backup") === "1",
    docker: formData.get("addon_docker") === "1",
  };

  // Optional SSH key added at deploy time
  const newKey = String(formData.get("sshPublicKey") ?? "").trim();
  const keyName = String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60);

  // Billing term (monthly / annual / 2yr / 3yr) with commitment discount
  const term = vpsTerm(Number(formData.get("termMonths") ?? 1));
  const wantsDedicatedIp = formData.get("dedicatedIp") === "1";
  const ipCents = wantsDedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
  // Mirrors lib/order.ts orderQuote so every VPS charge path agrees. Renewals in
  // worker/billing.ts bill the regular vpsTermPriceCents (untouched), so the
  // strikethrough shown on marketing pages is the real renewal price and this
  // discounted value is the real first-term price — displayed === charged.
  // (Dedicated IP is billed at full price; the promo only touches the plan.)
  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
  const promo = currentPromo(new Date());
  const chargeCents = promoPriceCents(regularPlanCents, promo) + ipCents;
  const promoNote = promo.discountPercent > 0 ? ` · ${promo.name} ${promo.discountPercent}% off first term` : "";

  const isAdmin = user.role === "ADMIN";
  const freeRequested = formData.get("free") === "1" && isAdmin;

  if (!freeRequested && user.balanceCents < chargeCents) {
    return { error: "Insufficient balance. Top up your wallet first." };
  }

  let server;
  try {
    server = await db.$transaction(async (tx) => {
    if (!freeRequested) {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -chargeCents,
          description: `Order: ${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`,
        },
      });
      // PAID invoice for the initial order (one distinct charge per order — the
      // new server row is created below, so there is no replay to dedupe).
      await tx.invoice.create({
        data: invoiceCreateData({
          userId: user.id,
          description: `Order: ${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`,
          status: "PAID",
          period: { start: new Date(), end: addMonths(new Date(), term.months) },
          lineItems: [
            { description: `${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`, qty: 1, unitCents: chargeCents, amountCents: chargeCents },
          ],
        }),
      });
    }
    if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
      const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
      if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
    }
    const s = await tx.server.create({
      data: {
        name: parsed.data.hostname,
        hostname: parsed.data.hostname,
        userId: user.id,
        planId: plan.id,
        osTemplateId: os.id,
        nodeId,
        addons,
        termMonths: term.months,
        wantsDedicatedIp,
        isFree: freeRequested,
        expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
      },
    });
    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
    return s;
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient balance. Top up your wallet first." };
    }
    throw e;
  }

  await audit(user.id, "server.order", `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo free=${freeRequested}`);
  // A first paid order can unlock a referral reward (free admin grants don't count).
  if (!freeRequested) {
    try {
      await maybeRewardReferral(user.id);
    } catch { /* non-fatal */ }
  }
  redirect(`/dashboard/servers/${server.id}`);
}

/**
 * Deploy flow that does NOT require pre-funding the wallet. If the wallet covers
 * the order (or it's a free admin grant) it provisions immediately; otherwise it
 * returns a Stripe Checkout URL for the order total, and the Stripe confirm route
 * provisions the server on successful payment.
 */
export async function payAndDeploy(
  prev: any,
  formData: FormData,
): Promise<{ error?: string; checkoutUrl?: string }> {
  const user = await requireUser();
  // Spend path: same impersonation guard as orderServer.
  await assertNotImpersonating();
  // Same per-user server cap as orderServer (this is the card-pay deploy path).
  const limitErr = await serverLimitError(user.id);
  if (limitErr) return { error: limitErr };
  const intent = intentFromFormData(formData);

  let quote;
  try {
    quote = await orderQuote(intent);
  } catch (e) {
    if (e instanceof OrderError) return { error: e.message };
    throw e;
  }

  const isAdmin = user.role === "ADMIN";
  const freePath = !!intent.free && isAdmin;

  // Wallet-aware split. The customer's Review screen computes the exact same split
  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
  // the balance. Free admin grants skip the split entirely (no money moves).
  const useWallet = formData.get("useWallet") !== "0";
  const { walletApplied, cardCents } = freePath
    ? { walletApplied: 0, cardCents: 0 }
    : walletSplit({ dueCents: quote.chargeCents, balanceCents: user.balanceCents, useWallet });

  // Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
  // (or nothing, for a free grant); the balance check inside it holds because a
  // $0 card portion means balance >= chargeCents.
  if (freePath || cardCents <= 0) {
    let serverId: string;
    try {
      serverId = await placeOrder(user, intent);
    } catch (e) {
      if (e instanceof OrderError) return { error: e.message };
      throw e;
    }
    redirect(`/dashboard/servers/${serverId}`);
  }

  // Card portion > 0 → charge ONLY the remainder on the card (not the full total).
  // On payment success the confirm route credits this card amount to the wallet and
  // then placeOrder debits the full chargeCents, so the wallet naturally absorbs
  // `walletApplied` and the card the rest — the wallet is never touched before the
  // card clears. (walletApplied is implied by cardCents vs. the recomputed charge,
  // so it needs no separate metadata field.)
  const url = await createOrderCheckout(user, cardCents, intent);
  if (!url) return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
  return { checkoutUrl: url };
}

// ---------- Server lifecycle ----------

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

export async function serverAction(serverId: string, action: string) {
  const { user, server } = await ownedServer(serverId);
  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
    start: "START",
    stop: "STOP",
    reboot: "REBOOT",
    reinstall: "REINSTALL",
    delete: "DELETE",
  };
  const type = allowed[action];
  if (!type) throw new Error("Invalid action");
  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
    throw new Error("Server is suspended");
  }

  // A reinstall wipes the whole VM, including any block-storage volume the VM
  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
  //
  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
  // deliberately keeps `serverId` set so the volume can be re-attached
  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
  // Filtering on ATTACHED therefore missed the worst case: customer fills a
  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
  // Reinstall — both guards see zero attached volumes, and the purge takes the
  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted

  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
  // by serverId; this path did not. That asymmetry was the bug.
  if (type === "REINSTALL") {
    const pinnedVolumes = await db.volume.count({ where: { serverId } });
    if (pinnedVolumes > 0) {
      throw new Error(
        "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
      );
    }
  }

  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) return; // debounce: one job at a time per server

  if (type === "DELETE") {
    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
  }
  await db.job.create({ data: { type, serverId } });
  await audit(user.id, `server.${action}`, serverId);
  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
  revalidatePath(`/dashboard/servers/${serverId}`);
}

// ---------- Wallet (demo top-up until a payment gateway is connected) ----------

export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  // Spend/credit path: block while impersonating so an admin can't mint or move
  // a customer's balance on their behalf.
  await assertNotImpersonating();
  // Security: never mint free wallet balance in production. The demo gateway that
  // credits without a real payment is only ever acceptable in non-production, and
  // is refused outright when NODE_ENV === "production" regardless of Stripe.
  if (process.env.NODE_ENV === "production") {
    return { error: "Please add funds with a card via the secure checkout." };
  }
  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
  // go through Checkout.
  const { stripeConfigured } = await import("./stripe");
  if (stripeConfigured()) {
    return { error: "Please add funds with a card via the secure checkout." };
  }
  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
  const topupHdrs = await headers();
  const topupIp = (topupHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
  if (!topupRl.ok) {
    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
  }
  const amount = Number(formData.get("amount"));
  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
    return { error: "Amount must be between $1 and $1000." };
  }
  const cents = Math.round(amount * 100);
  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
  const minTopup = await getSettingInt("min_topup_cents", 500);
  if (cents < minTopup) {
    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
  }

  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
  // sets. applyCouponToTopup re-validates for this user against the real amount.
  const jar = await cookies();
  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
  let bonusCents = 0;
  let couponId: string | null = null;
  let couponLabel = "";
  if (couponCode) {
    const result = await applyCouponToTopup(couponCode, cents);
    if (result.ok) {
      bonusCents = result.bonusCents;
      couponId = result.couponId;
      couponLabel = result.label;
    }
  }

  await db.$transaction([
    db.user.update({
      where: { id: user.id },
      data: { balanceCents: { increment: cents + bonusCents } },
    }),
    db.walletTransaction.create({
      data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
    }),
    ...(bonusCents > 0 && couponId
      ? [
          db.walletTransaction.create({
            data: {
              userId: user.id,
              amountCents: bonusCents,
              description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
            },
          }),
          db.couponRedemption.create({
            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
          }),
          db.coupon.update({
            where: { id: couponId },
            data: { timesRedeemed: { increment: 1 } },
          }),
        ]
      : []),
  ]);
  jar.delete(COUPON_COOKIE);
  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
  // First successful paid action may unlock a referral reward for both parties.
  try {
    await maybeRewardReferral(user.id);
  } catch { /* non-fatal */ }
  revalidatePath("/dashboard/billing");
  return {};
}

