209	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
210	  const serverId = String(formData.get("serverId") ?? "");
211	  const { user, server } = await ownedServer(serverId);
212	  const parsed = z
213	    .object({
214	      guestPort: z.coerce.number().int().min(1).max(65535),
215	      protocol: z.enum(["tcp", "udp"]),
216	    })
217	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
218	  if (!parsed.success) return { error: "Invalid port." };
219	
220	  const count = await db.portForward.count({ where: { serverId } });
221	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
222	
223	  const used = new Set([
224	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
225	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
226	  ]);
227	  let publicPort = 0;
228	  for (let p = PF_MIN; p <= PF_MAX; p++) {
229	    if (!used.has(p)) { publicPort = p; break; }
230	  }
231	  if (!publicPort) return { error: "No public ports available." };
232	
233	  await db.portForward.create({
234	    data: { serverId, publicPort, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
235	  });
