89	// ---------- Self-service backup restore ----------
90	
91	export type ServerBackup = { volid: string; ctime?: number; size?: number };
92	
93	/**
94	 * List the vzdump backups on the `backup` storage that belong to this server's
95	 * VMID. Read-only Proxmox call, ownership-checked.
96	 */
97	export async function listServerBackups(
98	  serverId: string
99	): Promise<{ error?: string; backups?: ServerBackup[] }> {
100	  const { server } = await ownedServer(serverId);
101	  if (!server.vmid) return { backups: [] };
102	  try {
103	    const backups = (await listBackups(server.vmid)) as ServerBackup[];
104	    backups.sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
105	    return { backups };
106	  } catch {
107	    return { error: "Could not reach the hypervisor — try again in a moment." };
108	  }
109	}
110	
111	/**
112	 * Enqueue a BACKUP_RESTORE job for the selected vzdump archive. This OVERWRITES
113	 * the server's current disk. The volid is validated against the server's own
114	 * backups so a customer can only restore their own VM's archives.
115	 */
116	export async function requestRestore(
117	  serverId: string,
118	  volid: string
119	): Promise<{ error?: string }> {
120	  const { user, server } = await ownedServer(serverId);
121	  if (!server.vmid) return { error: "Server has no VM yet." };
122	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
123	    return { error: "Server must be running or stopped to restore a backup." };
124	  }
125	
126	  // Validate the archive actually belongs to this server's VMID (prevents
127	  // restoring another customer's backup by guessing a volid).
128	  let owned: ServerBackup[];
129	  try {
130	    owned = (await listBackups(server.vmid)) as ServerBackup[];
131	  } catch {
132	    return { error: "Could not verify the backup — the hypervisor is briefly unavailable." };
133	  }
134	  if (!owned.some((b) => b.volid === volid)) {
135	    return { error: "That backup was not found for this server." };
136	  }
137	
138	  // DATA SAFETY (critical): `qmrestore --force` over an existing VM calls PVE's
139	  // destroy_vm first ("avoid zombie disks when restoring over an existing VM"),
140	  // and destroy_vm frees EVERY volume the vmid owns, `unusedN` entries included.
141	  // Restoring a backup taken before a volume was attached therefore destroys that
142	  // volume's data silently, while `Volume.diskName` keeps pointing at the dead
143	  // volid and billing carries on.
144	  //
145	  // Reinstall already refuses for exactly this reason. Restore does the same thing
146	  // to the same vmid and had no guard at all — same rule, both layers.
147	  const pinnedVolumes = await db.volume.count({ where: { serverId } });
148	  if (pinnedVolumes > 0) {
149	    return {
150	      error:
151	        `Restoring replaces this server's disks, which would also destroy the ` +
152	        `${pinnedVolumes} data volume${pinnedVolumes === 1 ? "" : "s"} assigned to it — ` +
153	        `including any you have detached. Move or delete them first, then restore.`,
154	    };
155	  }
156	
157	  const idle = await ensureIdle(serverId);
158	  if (idle.error) return idle;
159	
160	  await db.job.create({ data: { type: "BACKUP_RESTORE", serverId, payload: { volid } } });
161	  await db.auditLog.create({
162	    data: { userId: user.id, action: "server.backup_restore", detail: `${serverId} ${volid}` },
163	  });
164	  revalidatePath(`/dashboard/servers/${serverId}`);
165	  return {};
166	}
