66	
67	/** Connection details for a specific Node row (see Prisma `Node`). */
68	export type NodeConn = {
69	  apiUrl: string;
70	  pveNode: string;
71	  tokenId: string;
72	  tokenSecret: string;
73	};
74	
75	export type PveClient = {
76	  get: (path: string, params?: Record<string, any>) => Promise<any>;
77	  post: (path: string, params?: Record<string, any>) => Promise<any>;
78	  put: (path: string, params?: Record<string, any>) => Promise<any>;
79	  del: (path: string, params?: Record<string, any>) => Promise<any>;
80	  node: string;
81	  waitForTask: (upid: string, timeoutMs?: number) => Promise<void>;
82	  nextVmid: () => Promise<number>;
83	  vmStatus: (vmid: number) => Promise<any>;
84	};
